   x,y=st.pop();pts.append((x,y))
   for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=nx<R and 0<=ny<C and a[nx][ny]==col and (nx,ny) not in seen:seen.add((nx,ny));st.append((nx,ny))
  if col==0 and any(x in(0,R-1) or y in(0,C-1) for x,y in pts): comps.append(pts)
print('dims',R,C,'edge 0 comps',[(len(p),sorted(p)) for p in comps])
